1095	/** id 로 문서 콘텐츠 해석 — 전용 템플릿 우선, 없으면 자동 생성. */
1096	export function resolveDoc(id: string): DocTemplate | undefined {
1097	  // IVDR 전용 상세 템플릿
1098	  const leaf = leafById(id);
1099	  const detailed = docById(id);
1100	  if (detailed) {
1101	    // 준비물·취지는 docTree(잎/맵)에서 단일 출처로 관리 → 전용 템플릿에도 주입
1102	    const m = metaFor(id);
1103	    return {
1104	      ...detailed,
1105	      rationale: rationaleFor(id),
1106	      difficulty: m?.difficulty,
1107	      importance: m?.importance,
1108	      effort: effortFor(id),
1109	      prepDocs: prepDocsFor(id),
1110	      knowledge: knowledgeFor(id),
1111	      prerequisites: leaf?.prerequisites ?? [],
1112	    };
1113	  }
1114	  // IVDR 자동 생성 템플릿
1115	  if (leaf) {
1116	    const station = stations.find((s) => s.id === leaf.stationId);
1117	    if (station) return buildGenericDoc(leaf, station);
1118	  }
1119	  // ISO 13485 상세 템플릿
1120	  const isoDetailed = iso13485DocById(id);
1121	  if (isoDetailed) return isoDetailed;
1122	  // ISO 13485 자동 생성 템플릿
1123	  const isoLeaf = iso13485LeafById(id);
1124	  if (isoLeaf) {
1125	    return {
1126	      id: isoLeaf.id,
1127	      stationId: isoLeaf.stationId,
1128	      docTitle: isoLeaf.title,
1129	      purpose: isoLeaf.note ?? `ISO 13485 Clause ${isoLeaf.refs.join("·")} 요건을 충족하는 문서입니다.`,
1130	      sections: [
1131	        {
1132	          heading: "1. 내용",
1133	          guidance: "ISO 13485 요구사항에 따라 작성한다.",
1134	          placeholder: `[${isoLeaf.title} 내용을 여기에 작성하세요]`,
1135	        },
1136	      ],
1137	      checklist: [`${isoLeaf.title} 내용이 ISO 13485 Clause ${isoLeaf.refs.join("·")} 요건을 충족한다`],
1138	      relatedConceptSlugs: ["iso-13485"],
1139	      refs: isoLeaf.refs.map((r) => `ISO 13485:2016 Clause ${r}`),
1140	    };
1141	  }
1142	  return undefined;
1143	}
