1145	/** 복사/.md 다운로드용 마크다운 생성. */
1146	export function toMarkdown(t: DocTemplate): string {
1147	  const lines: string[] = [];
1148	  lines.push(`# ${t.docTitle}`);
1149	  lines.push("");
1150	  lines.push(`> 목적: ${t.purpose}`);
1151	  lines.push(`> 관련 조항: ${t.refs.join(" · ")}`);
1152	  if (t.difficulty && t.importance) {
1153	    lines.push(`> 난이도: ${difficultyLabel[t.difficulty]} · 중요도: ${importanceLabel[t.importance]}`);
1154	  }
1155	  if (t.effort) {
1156	    lines.push(`> 예상 소요(추정): ${t.effort.total} — 자료확보 ${t.effort.gather} · 맥락이해 ${t.effort.context} · 작성 ${t.effort.draft} · 검토 ${t.effort.review} · RA 피드백 ${t.effort.raRounds}회`);
1157	  }
1158	  lines.push("");
1159	  if (t.rationale) {
1160	    lines.push(`## 취지 — 왜 이 문서를 쓰는가`);
1161	    lines.push(t.rationale);
1162	    lines.push("");
1163	  }
1164	  if (t.prepDocs && t.prepDocs.length) {
1165	    lines.push(`## 미리 만들어두면 좋은 문서`);
1166	    for (const id of t.prepDocs) {
1167	      const l = leafById(id);
1168	      if (l) lines.push(`- ${l.title}`);
1169	    }
1170	    lines.push("");
1171	  }
1172	  if (t.knowledge && t.knowledge.length) {
1173	    lines.push(`## 작성 전 알아야 할 것`);
1174	    for (const k of t.knowledge) lines.push(`- [ ] ${k}`);
1175	    lines.push("");
1176	  }
1177	  if (t.prerequisites && t.prerequisites.length) {
1178	    lines.push(`## 작성 전 준비물`);
1179	    for (const p of t.prerequisites) {
1180	      lines.push(`- [ ] (${prereqKindLabel[p.kind]}) ${p.label}`);
1181	    }
1182	    lines.push("");
1183	  }
1184	  for (const s of t.sections) {
1185	    lines.push(`## ${s.heading}`);
1186	    lines.push(`<!-- ${s.guidance} -->`);
1187	    lines.push("");
1188	    lines.push(s.placeholder);
1189	    lines.push("");
1190	  }
1191	  lines.push(`## 완료 체크리스트`);
1192	  for (const c of t.checklist) lines.push(`- [ ] ${c}`);
1193	  lines.push("");
1194	  lines.push(
1195	    `---\n_IVDR 여정 위키 생성 템플릿. 규제 사실은 최신 관보·NB 요건으로 재확인할 것. 본 문서는 정보 제공용이며 법적 자문이 아님._`,
1196	  );
1197	  return lines.join("\n");
1198	}
